'use strict';
const assert=require('node:assert/strict'),fs=require('node:fs'),cp=require('node:child_process');
const {reconcile}=require('./lib/reconcile.cjs');
const input=[{record_id:'B',revision:2,title:'Shared',owner:'old',extra:'keep-old-only'},{record_id:'A',revision:1,title:'Shared',owner:'other'},{record_id:'B',revision:12,title:'Revised',owner:'new'},{record_id:'C',revision:0,title:'Alpha',owner:'third'},{record_id:'A',revision:1,title:'Tie loses',owner:'late'}];
const before=JSON.stringify(input);input.forEach(Object.freeze);Object.freeze(input);
assert.deepEqual(reconcile(input),[{record_id:'B',revision:12,title:'Revised',owner:'new'},{record_id:'A',revision:1,title:'Shared',owner:'other'},{record_id:'C',revision:0,title:'Alpha',owner:'third'}]);
assert.equal(JSON.stringify(input),before);assert.deepEqual(reconcile([]),[]);
for(const rows of [null,{},[null],[{record_id:'',revision:0}],[{record_id:7,revision:0}],[{record_id:'A',revision:-1}],[{record_id:'A',revision:1.5}],[{record_id:'A',revision:'12'}],[{record_id:'A',revision:Number.MAX_SAFE_INTEGER+1}]])assert.throws(()=>reconcile(rows),TypeError);
assert.deepEqual(reconcile([{record_id:'X',revision:Number.MAX_SAFE_INTEGER-1},{record_id:'X',revision:Number.MAX_SAFE_INTEGER}]),[{record_id:'X',revision:Number.MAX_SAFE_INTEGER}]);
const result=cp.spawnSync(process.execPath,['bin/reconcile.cjs','data/work-orders.json'],{encoding:'utf8',timeout:3000,windowsHide:true});assert.equal(result.status,0,result.stderr);
assert.deepEqual(JSON.parse(result.stdout),[{record_id:'W-9',revision:12,title:'Paint benches',status:'assigned',owner:'Cy'},{record_id:'W-3',revision:2,title:'Repair rail',status:'assigned',owner:'Eli'},{record_id:'W-5',revision:0,title:'Clear path',status:'open',owner:'Dee'}]);assert(result.stdout.endsWith('\n'));console.log('Contract probe passed.');
